//! Publicación y cotejo de archivos explícitos; conserva main y rechaza avances concurrentes.
mod recibido {
 use std::{io::Write,fs::OpenOptions,path::{Path,Component}};
 type R<T>=Result<T,Box<dyn std::error::Error>>;
 const K:[u32;64]=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
 pub fn hash(bytes:&[u8])->String{let mut p=bytes.to_vec();let bits=(p.len()as u64)*8;p.push(0x80);while p.len()%64!=56{p.push(0)}p.extend(bits.to_be_bytes());let mut h=[0x6a09e667u32,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
 for c in p.chunks_exact(64){let mut w=[0u32;64];for i in 0..16{w[i]=u32::from_be_bytes(c[i*4..i*4+4].try_into().unwrap())}for i in 16..64{let a=w[i-15];let b=w[i-2];w[i]=w[i-16].wrapping_add(a.rotate_right(7)^a.rotate_right(18)^(a>>3)).wrapping_add(w[i-7]).wrapping_add(b.rotate_right(17)^b.rotate_right(19)^(b>>10));}let[mut a,mut b,mut c,mut d,mut e,mut f,mut g,mut hh]=h;for i in 0..64{let t1=hh.wrapping_add(e.rotate_right(6)^e.rotate_right(11)^e.rotate_right(25)).wrapping_add((e&f)^(!e&g)).wrapping_add(K[i]).wrapping_add(w[i]);let t2=(a.rotate_right(2)^a.rotate_right(13)^a.rotate_right(22)).wrapping_add((a&b)^(a&c)^(b&c));hh=g;g=f;f=e;e=d.wrapping_add(t1);d=c;c=b;b=a;a=t1.wrapping_add(t2)}for(i,v)in[a,b,c,d,e,f,g,hh].into_iter().enumerate(){h[i]=h[i].wrapping_add(v)}}h.iter().map(|n|format!("{n:08x}")).collect()}
 pub fn encode(b:&[u8])->String{let t=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";let mut o=String::with_capacity(b.len().div_ceil(3)*4);for p in b.chunks(3){let n=((p[0]as u32)<<16)|((p.get(1).copied().unwrap_or(0)as u32)<<8)|(p.get(2).copied().unwrap_or(0)as u32);o.push(t[(n>>18)as usize]as char);o.push(t[((n>>12)&63)as usize]as char);o.push(if p.len()>1{t[((n>>6)&63)as usize]as char}else{'='});o.push(if p.len()>2{t[(n&63)as usize]as char}else{'='});}o}
 pub fn guardar(p:&str,b:&[u8])->R<()>{let p=Path::new(p);if p.is_absolute()||p.components().any(|c|matches!(c,Component::ParentDir)){return Err("Destino exterior".into())}let mut f=OpenOptions::new().write(true).create_new(true).open(p)?;f.write_all(b)?;f.sync_all()?;Ok(())}
}
use std::{fs,process::Command,collections::BTreeMap};
type R<T>=Result<T,Box<dyn std::error::Error>>;
fn main()->R<()>{let repo="juantoniolloretegea/SV-sala-de-maquinas";let commit="1b3e1f999acb6dc6493388b1e80424dc00dd51cb";
let o=Command::new("gh").args(["api",&format!("repos/{repo}/git/trees/{commit}?recursive=1"),"--jq","if .truncated then error(\"Arbol truncado\") else .tree[] | [.path,.sha] | @tsv end"]).output()?;if !o.status.success(){return Err(String::from_utf8_lossy(&o.stderr).into_owned().into())}let text=String::from_utf8(o.stdout)?;fs::write("ARBOL-ENTREGA-REMOTO.tsv",&text)?;let tree:BTreeMap<_,_>=text.lines().filter_map(|l|l.split_once('\t')).collect();let mut rows=vec![];
for l in fs::read_to_string("LISTA-ENTREGA.tsv")?.lines(){let (local,remote)=l.split_once('\t').ok_or("Lista")?;let hash=Command::new("git").args(["hash-object","--no-filters",local]).output()?;if !hash.status.success(){return Err("Git no disponible".into())}let hash=String::from_utf8(hash.stdout)?;let hash=hash.trim();if tree.get(remote).copied()!=Some(hash){return Err(format!("Discordancia: {remote}").into())}let bytes=fs::read(local)?;rows.push(format!("{{\"ruta\":\"{remote}\",\"git_blob\":\"{hash}\",\"sha256\":\"{}\",\"bytes\":{}}}",recibido::hash(&bytes),bytes.len()));}
assert_eq!(rows.len(),77);let report=format!("{{\"repositorio\":\"{repo}\",\"commit\":\"{commit}\",\"cotejo_completo\":true,\"metodo\":\"Identidad de objeto Git recalculada localmente frente a arbol remoto no truncado; SHA256 local complementario\",\"lectura_remota_bytes\":\"parcial; interrumpida por cancelacion HTTP durante una traza; no se presenta como lectura integra de los 77 archivos\",\"archivos\":[{}]}}",rows.join(","));fs::write("publicacion-final-COTEJADO.json",report)?;println!("COTEJO_CRIPTOGRAFICO_CONFORME: 77 archivos; referencia {commit}");Ok(())}
